// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient) public {
        // Ensure caller is not the owner
        vm.assume(recipient != address(this) && recipient != address(0));
        uint256 balanceBefore = address(c).balance;
        // Fund the contract
        vm.deal(address(c), 1 ether);
        // Call withdrawAll as a non-owner
        vm.prank(recipient);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, address(0x1234)));
        // The call must revert because msg.sender != owner
        assertTrue(!success && address(c).balance == balanceBefore + 1 ether);
    }
}

